		'/admin/users',
		{
			schema: {
				body: {
					type: 'object',
					required: ['venueId', 'name', 'login', 'password', 'role'],
					properties: {
						venueId: { type: 'string', format: 'uuid' },
						name: { type: 'string', minLength: 1, maxLength: 120 },
