			querystring: {
				type: 'object',
				properties: {
					venueId: { type: 'string' },
					from: { type: 'string' },
					to: { type: 'string' },
					status: { type: 'string' },
					source: { type: 'string' },
					seatingAreaId: { type: 'string' },
					occasion: { type: 'string' },
				},
			},
		},
	},
